import { useMemo, useState } from "react";
import { Alert, FlatList, Keyboard, KeyboardAvoidingView, Modal, Platform, Pressable, ScrollView, StyleSheet, Text, TextInput, View } from "react-native";
import { ScreenContainer } from "@/components/screen-container";
import { IconSymbol } from "@/components/ui/icon-symbol";
import { useColors } from "@/hooks/use-colors";
import { trpc } from "@/lib/trpc";
import { printReceipt, shareInvoicePdf } from "@/lib/invoice-sharing";

type Section = "home" | "invoice" | "stock" | "customers" | "reports" | "expenses" | "settings";
type DraftLine = { productId: number; name: string; quantity: number; price: number; stock: number };
type FreeLine = { description: string; quantity: number; unitPrice: number };
const money = (v: number | string, currency = "ر.س") => `${Number(v || 0).toFixed(2)} ${currency}`;
const todayRange = () => { const from = new Date(); from.setHours(0, 0, 0, 0); const to = new Date(from); to.setDate(to.getDate() + 1); return { from, to }; };
const safeDate = (v: any) => v ? new Date(v).toLocaleString("ar-SA") : "";

export default function HomeScreen() {
  const colors = useColors();
  const [section, setSection] = useState<Section>("home");
  const [search, setSearch] = useState("");
  const [invoiceMode, setInvoiceMode] = useState<"stock" | "free">("stock");
  const [showInvoice, setShowInvoice] = useState(false);
  const [showCustomer, setShowCustomer] = useState(false);
  const [showProduct, setShowProduct] = useState(false);
  const [showAccount, setShowAccount] = useState(false);
  const [showInvoiceDetail, setShowInvoiceDetail] = useState(false);
  const [showMore, setShowMore] = useState(false);
  const [selectedCustomerId, setSelectedCustomerId] = useState<number | null>(null);
  const [selectedInvoiceId, setSelectedInvoiceId] = useState<number | null>(null);
  const [selectedFreeId, setSelectedFreeId] = useState<number | null>(null);
  const [invoiceLines, setInvoiceLines] = useState<DraftLine[]>([]);
  const [freeLines, setFreeLines] = useState<FreeLine[]>([]);
  const [freeCustomer, setFreeCustomer] = useState("");
  const [freeDescription, setFreeDescription] = useState("");
  const [freeQty, setFreeQty] = useState("1");
  const [freePrice, setFreePrice] = useState("");
  const [customerId, setCustomerId] = useState<number | null>(null);
  const [customerName, setCustomerName] = useState("");
  const [customerPhone, setCustomerPhone] = useState("");
  const [customerAddress, setCustomerAddress] = useState("");
  const [customerNotes, setCustomerNotes] = useState("");
  const [productId, setProductId] = useState<number | null>(null);
  const [productName, setProductName] = useState("");
  const [productPurchase, setProductPurchase] = useState("");
  const [productSale, setProductSale] = useState("");
  const [productStock, setProductStock] = useState("");
  const [productMin, setProductMin] = useState("");
  const [expenseId, setExpenseId] = useState<number | null>(null);
  const [expenseCategory, setExpenseCategory] = useState("");
  const [expenseAmount, setExpenseAmount] = useState("");
  const [expenseNotes, setExpenseNotes] = useState("");
  const [settingsName, setSettingsName] = useState("");
  const [settingsPhone, setSettingsPhone] = useState("");
  const [settingsAddress, setSettingsAddress] = useState("");
  const [settingsCurrency, setSettingsCurrency] = useState("ر.س");
  const [settingsWidth, setSettingsWidth] = useState<"58mm" | "80mm">("80mm");
  const [accountPaymentAmount, setAccountPaymentAmount] = useState("");
  const [accountPaymentNotes, setAccountPaymentNotes] = useState("");

  const productsQ = trpc.products.list.useQuery({ search: search || undefined });
  const customersQ = trpc.customers.list.useQuery({ search: search || undefined });
  const invoicesQ = trpc.sales.recent.useQuery({ limit: 50 });
  const freeQ = trpc.freeInvoices.recent.useQuery({ limit: 50 });
  const reportQ = trpc.reports.summary.useQuery(todayRange());
  const activityQ = trpc.activity.useQuery({ limit: 100 });
  const expensesQ = trpc.expenses.list.useQuery();
  const settingsQ = trpc.settings.get.useQuery();
  const accountQ = trpc.customers.account.useQuery({ customerId: selectedCustomerId ?? 0 }, { enabled: !!selectedCustomerId });
  const invoiceDetailQ = trpc.sales.detail.useQuery({ id: selectedInvoiceId ?? 0 }, { enabled: !!selectedInvoiceId });
  const freeDetailQ = trpc.freeInvoices.detail.useQuery({ id: selectedFreeId ?? 0 }, { enabled: !!selectedFreeId });

  const createCustomer = trpc.customers.create.useMutation({ onSuccess: () => { customersQ.refetch(); closeCustomer(); Alert.alert("تم الحفظ", "تمت إضافة الحساب."); } });
  const updateCustomer = trpc.customers.update.useMutation({ onSuccess: () => { customersQ.refetch(); accountQ.refetch(); closeCustomer(); Alert.alert("تم التعديل", "تم تحديث بيانات الحساب."); } });
  const createProduct = trpc.products.create.useMutation({ onSuccess: () => { productsQ.refetch(); closeProduct(); Alert.alert("تم الحفظ", "تمت إضافة الصنف."); } });
  const updateProduct = trpc.products.update.useMutation({ onSuccess: () => { productsQ.refetch(); closeProduct(); Alert.alert("تم التعديل", "تم تحديث الصنف."); } });
  const createSale = trpc.sales.create.useMutation({ onSuccess: async (data) => { await refreshAll(); closeInvoice(); Alert.alert("تم حفظ الفاتورة", `رقم ${data.invoiceNo}\nالإجمالي ${money(data.total, settingsCurrency)}`, [{ text: "إغلاق" }, { text: "طباعة", onPress: () => void printReceipt(data.items.map((x: any) => ({ name: x.name, quantity: x.quantity, unitPrice: x.unitPrice })), undefined, settingsWidth) }, { text: "مشاركة PDF", onPress: () => void shareInvoicePdf(data.items.map((x: any) => ({ name: x.name, quantity: x.quantity, unitPrice: x.unitPrice })), undefined, undefined, settingsWidth) }]); } });
  const createFree = trpc.freeInvoices.create.useMutation({ onSuccess: async (data) => { await refreshAll(); closeInvoice(); Alert.alert("تم حفظ الفاتورة الحرة", `رقم ${data.invoiceNo}`); } });
  const updateFree = trpc.freeInvoices.update.useMutation({ onSuccess: async () => { await refreshAll(); setSelectedFreeId(null); Alert.alert("تم التعديل", "تم تحديث الفاتورة الحرة."); } });
  const deleteFree = trpc.freeInvoices.delete.useMutation({ onSuccess: async () => { await refreshAll(); setSelectedFreeId(null); setShowInvoiceDetail(false); Alert.alert("تم الحذف", "تم حذف الفاتورة الحرة."); } });
  const updateSale = trpc.sales.update.useMutation({ onSuccess: async () => { await refreshAll(); setSelectedInvoiceId(null); setShowInvoiceDetail(false); Alert.alert("تم التعديل", "تم تحديث الفاتورة والمخزون."); } });
  const deleteSale = trpc.sales.delete.useMutation({ onSuccess: async () => { await refreshAll(); setSelectedInvoiceId(null); setShowInvoiceDetail(false); Alert.alert("تم الحذف", "تم حذف الفاتورة وإرجاع الكميات للمخزون."); } });
  const createPayment = trpc.customers.payment.useMutation({ onSuccess: async () => { await refreshAll(); setAccountPaymentAmount(""); setAccountPaymentNotes(""); Alert.alert("تم تسجيل الدفعة", "تم تحديث رصيد الحساب."); } });
  const updatePayment = trpc.customers.updatePayment.useMutation({ onSuccess: () => { accountQ.refetch(); customersQ.refetch(); activityQ.refetch(); } });
  const deletePayment = trpc.customers.deletePayment.useMutation({ onSuccess: () => { accountQ.refetch(); customersQ.refetch(); activityQ.refetch(); } });
  const createExpense = trpc.expenses.create.useMutation({ onSuccess: async () => { await refreshAll(); closeExpense(); Alert.alert("تم الحفظ", "تم تسجيل المصروف."); } });
  const updateExpense = trpc.expenses.update.useMutation({ onSuccess: async () => { await refreshAll(); closeExpense(); Alert.alert("تم التعديل", "تم تحديث المصروف."); } });
  const deleteExpense = trpc.expenses.delete.useMutation({ onSuccess: () => { expensesQ.refetch(); activityQ.refetch(); reportQ.refetch(); } });
  const updateSettings = trpc.settings.update.useMutation({ onSuccess: async () => { await settingsQ.refetch(); Alert.alert("تم الحفظ", "تم تحديث إعدادات التطبيق."); } });

  const products = productsQ.data ?? [];
  const customers = customersQ.data ?? [];
  const invoices = invoicesQ.data ?? [];
  const freeInvoices = freeQ.data ?? [];
  const activities = activityQ.data ?? [];
  const expenses = expensesQ.data ?? [];
  const lowStock = products.filter((p: any) => Number(p.stock) <= Number(p.minStock));
  const draftTotal = useMemo(() => invoiceLines.reduce((s, x) => s + x.quantity * x.price, 0), [invoiceLines]);
  const freeTotal = useMemo(() => freeLines.reduce((s, x) => s + x.quantity * x.unitPrice, 0), [freeLines]);
  const title = { home: "الرئيسية", invoice: "الفواتير", stock: "الأصناف والمخزون", customers: "الحسابات والعملاء", reports: "التقارير والسجل", expenses: "المصروفات", settings: "الإعدادات" }[section];

  function refreshAll() { return Promise.all([productsQ.refetch(), customersQ.refetch(), invoicesQ.refetch(), freeQ.refetch(), reportQ.refetch(), activityQ.refetch(), expensesQ.refetch(), accountQ.refetch()]); }
  function openInvoice(mode: "stock" | "free") { setInvoiceMode(mode); setShowInvoice(true); }
  function closeInvoice() { Keyboard.dismiss(); setShowInvoice(false); setInvoiceLines([]); setFreeLines([]); setFreeCustomer(""); setFreeDescription(""); setFreeQty("1"); setFreePrice(""); }
  function closeCustomer() { Keyboard.dismiss(); setShowCustomer(false); setCustomerId(null); setCustomerName(""); setCustomerPhone(""); setCustomerAddress(""); setCustomerNotes(""); }
  function closeProduct() { Keyboard.dismiss(); setShowProduct(false); setProductId(null); setProductName(""); setProductPurchase(""); setProductSale(""); setProductStock(""); setProductMin(""); }
  function closeExpense() { setExpenseId(null); setExpenseCategory(""); setExpenseAmount(""); setExpenseNotes(""); }
  function addStockLine(p: any) { setInvoiceLines((old) => { const found = old.find((x) => x.productId === p.id); if (found) return old.map((x) => x.productId === p.id ? { ...x, quantity: x.quantity + 1 } : x); return [...old, { productId: p.id, name: p.name, quantity: 1, price: Number(p.salePrice), stock: Number(p.stock) }]; }); }
  function addFreeLine() { const q = Number(freeQty), price = Number(freePrice); if (!freeDescription.trim() || !q || !Number.isFinite(price) || price < 0) return Alert.alert("تنبيه", "أدخل البيان والكمية والسعر."); setFreeLines((x) => [...x, { description: freeDescription.trim(), quantity: q, unitPrice: price }]); setFreeDescription(""); setFreeQty("1"); setFreePrice(""); }
  function saveStockInvoice() { if (!invoiceLines.length) return Alert.alert("الفاتورة فارغة", "أضف صنفًا واحدًا على الأقل."); const bad = invoiceLines.find((x) => x.quantity > x.stock); if (bad) return Alert.alert("المخزون غير كافٍ", `${bad.name}: المتوفر ${bad.stock}`); createSale.mutate({ customerId, paymentType: customerId ? "credit" : "cash", paid: customerId ? 0 : draftTotal, discount: 0, items: invoiceLines.map((x) => ({ productId: x.productId, quantity: x.quantity })) }); }
  function saveFreeInvoice() { if (!freeLines.length) return Alert.alert("الفاتورة فارغة", "أضف بندًا واحدًا على الأقل."); createFree.mutate({ customerName: freeCustomer.trim() || undefined, items: freeLines }); }
  function openCustomer(c: any) { setSelectedCustomerId(c.id); setShowAccount(true); }
  function editCustomer(c: any) { setCustomerId(c.id); setCustomerName(c.name); setCustomerPhone(c.phone || ""); setCustomerAddress(c.address || ""); setCustomerNotes(c.notes || ""); setShowCustomer(true); }
  function saveCustomer() { if (!customerName.trim()) return Alert.alert("تنبيه", "اكتب اسم الحساب."); const payload = { name: customerName.trim(), phone: customerPhone.trim() || undefined, address: customerAddress.trim() || undefined, notes: customerNotes.trim() || undefined }; if (customerId) updateCustomer.mutate({ id: customerId, ...payload }); else createCustomer.mutate({ ...payload, openingBalance: 0 }); }
  function editProduct(p: any) { setProductId(p.id); setProductName(p.name); setProductPurchase(String(p.purchasePrice)); setProductSale(String(p.salePrice)); setProductStock(String(p.stock)); setProductMin(String(p.minStock)); setShowProduct(true); }
  function saveProduct() { const sale = Number(productSale), purchase = Number(productPurchase) || 0, stock = Number(productStock) || 0, min = Number(productMin) || 0; if (!productName.trim() || !Number.isFinite(sale) || sale < 0) return Alert.alert("تنبيه", "أدخل اسم الصنف وسعر بيع صحيح."); if (productId) updateProduct.mutate({ id: productId, name: productName.trim(), purchasePrice: purchase, salePrice: sale, minStock: min, unit: "حبة" }); else createProduct.mutate({ name: productName.trim(), purchasePrice: purchase, salePrice: sale, stock, minStock: min, unit: "حبة" }); }
  function openExpense(e?: any) { if (e) { setExpenseId(e.id); setExpenseCategory(e.category); setExpenseAmount(String(e.amount)); setExpenseNotes(e.notes || ""); } else { closeExpense(); } }
  function saveExpense() { const amount = Number(expenseAmount); if (!expenseCategory.trim() || !amount) return Alert.alert("تنبيه", "أدخل نوع المصروف والمبلغ."); const payload = { category: expenseCategory.trim(), amount, notes: expenseNotes.trim() || undefined }; if (expenseId) updateExpense.mutate({ id: expenseId, ...payload }); else createExpense.mutate(payload); }
  function loadSettings() { const s: any = settingsQ.data; if (!s) return; setSettingsName(s.storeName || ""); setSettingsPhone(s.phone || ""); setSettingsAddress(s.address || ""); setSettingsCurrency(s.currency || "ر.س"); setSettingsWidth(s.receiptWidth || "80mm"); }
  function saveSettings() { updateSettings.mutate({ storeName: settingsName.trim() || "بقالة العزي للمواد الغذائية", phone: settingsPhone.trim() || undefined, address: settingsAddress.trim() || undefined, currency: settingsCurrency.trim() || "ر.س", receiptWidth: settingsWidth }); }
  function showSaleDetail(id: number) { setSelectedInvoiceId(id); setSelectedFreeId(null); setShowInvoiceDetail(true); }
  function showFreeDetail(id: number) { setSelectedFreeId(id); setSelectedInvoiceId(null); setShowInvoiceDetail(true); }
  function shareSaleDetail() { const d: any = invoiceDetailQ.data; if (!d) return; const lines = d.items.map((x: any) => ({ name: x.productName, quantity: Number(x.quantity), unitPrice: Number(x.unitPrice) })); void shareInvoicePdf(lines, d.customer?.name, d.customer?.phone, settingsWidth); }
  function printSaleDetail() { const d: any = invoiceDetailQ.data; if (!d) return; const lines = d.items.map((x: any) => ({ name: x.productName, quantity: Number(x.quantity), unitPrice: Number(x.unitPrice) })); void printReceipt(lines, d.customer?.name, settingsWidth); }
  function shareFreeDetail() { const d: any = freeDetailQ.data; if (!d) return; const lines = d.items.map((x: any) => ({ name: x.description, quantity: Number(x.quantity), unitPrice: Number(x.unitPrice) })); void shareInvoicePdf(lines, d.invoice.customerName || undefined, undefined, settingsWidth); }
  function printFreeDetail() { const d: any = freeDetailQ.data; if (!d) return; const lines = d.items.map((x: any) => ({ name: x.description, quantity: Number(x.quantity), unitPrice: Number(x.unitPrice) })); void printReceipt(lines, d.invoice.customerName || undefined, settingsWidth); }
  function deleteSaleConfirm(id: number) { Alert.alert("حذف الفاتورة", "سيتم حذف العملية وإرجاع الكميات للمخزون.", [{ text: "إلغاء", style: "cancel" }, { text: "حذف", style: "destructive", onPress: () => deleteSale.mutate({ id }) }]); }
  function deleteFreeConfirm(id: number) { Alert.alert("حذف الفاتورة", "هل تريد حذف الفاتورة الحرة؟", [{ text: "إلغاء", style: "cancel" }, { text: "حذف", style: "destructive", onPress: () => deleteFree.mutate({ id }) }]); }
  function accountShare() { const a: any = accountQ.data; if (!a) return; const lines = [...(a.invoices || []).map((x: any) => ({ name: `فاتورة ${x.invoiceNo}`, quantity: 1, unitPrice: Number(x.total) })), ...(a.payments || []).map((x: any) => ({ name: `دفعة - ${x.notes || "سداد"}`, quantity: 1, unitPrice: -Number(x.amount) }))]; void shareInvoicePdf(lines, a.customer?.name, a.customer?.phone, settingsWidth); }
  function accountPrint() { const a: any = accountQ.data; if (!a) return; const lines = [...(a.invoices || []).map((x: any) => ({ name: `فاتورة ${x.invoiceNo}`, quantity: 1, unitPrice: Number(x.total) })), ...(a.payments || []).map((x: any) => ({ name: `دفعة - ${x.notes || "سداد"}`, quantity: 1, unitPrice: -Number(x.amount) }))]; void printReceipt(lines, a.customer?.name, settingsWidth); }
  function addPayment() { const amount = Number(accountPaymentAmount); if (!selectedCustomerId || !amount) return Alert.alert("تنبيه", "أدخل مبلغ الدفعة."); createPayment.mutate({ customerId: selectedCustomerId, amount, notes: accountPaymentNotes.trim() || undefined }); }

  return (
    <ScreenContainer className="px-4 pt-3" safeAreaClassName="bg-background">
      <View style={styles.page}>
        <View style={styles.header}>
          <View><Text style={[styles.brand, { color: colors.primary }]}>بقالة العزي</Text><Text style={[styles.title, { color: colors.foreground }]}>{title}</Text></View>
          <Pressable onPress={() => { setSection("settings"); loadSettings(); }} style={[styles.logo, { backgroundColor: colors.primary }]}><IconSymbol name="gearshape.fill" size={23} color="#fff" /></Pressable>
        </View>
        <ScrollView showsVerticalScrollIndicator={false} contentContainerStyle={styles.scroll} keyboardShouldPersistTaps="handled">
          {section === "home" && <Home colors={colors} report={reportQ.data} lowStock={lowStock} onStock={() => openInvoice("stock")} onFree={() => openInvoice("free")} onCustomer={() => { closeCustomer(); setShowCustomer(true); }} onProduct={() => { closeProduct(); setShowProduct(true); }} onSection={setSection} activities={activities.slice(0, 8)} onActivity={(x: any) => x.type === "sale" ? showSaleDetail(x.referenceId) : x.type === "free" ? showFreeDetail(x.referenceId) : x.type === "payment" ? setSection("customers") : setSection("reports")} currency={settingsCurrency} />}
          {section === "invoice" && <Invoices colors={colors} invoices={invoices} freeInvoices={freeInvoices} onNewStock={() => openInvoice("stock")} onNewFree={() => openInvoice("free")} onOpen={showSaleDetail} onOpenFree={showFreeDetail} currency={settingsCurrency} />}
          {section === "stock" && <Stock colors={colors} products={products} lowStock={lowStock} search={search} setSearch={setSearch} onAdd={() => { closeProduct(); setShowProduct(true); }} onEdit={editProduct} currency={settingsCurrency} />}
          {section === "customers" && <Customers colors={colors} customers={customers} search={search} setSearch={setSearch} onAdd={() => { closeCustomer(); setShowCustomer(true); }} onEdit={editCustomer} onOpen={openCustomer} currency={settingsCurrency} />}
          {section === "reports" && <Reports colors={colors} report={reportQ.data} activities={activities} onOpenSale={showSaleDetail} onOpenFree={showFreeDetail} currency={settingsCurrency} />}
          {section === "expenses" && <Expenses colors={colors} expenses={expenses} category={expenseCategory} amount={expenseAmount} notes={expenseNotes} setCategory={setExpenseCategory} setAmount={setExpenseAmount} setNotes={setExpenseNotes} onSave={saveExpense} onEdit={openExpense} onDelete={(id: number) => Alert.alert("حذف المصروف", "هل تريد حذف المصروف؟", [{ text: "إلغاء", style: "cancel" }, { text: "حذف", style: "destructive", onPress: () => deleteExpense.mutate({ id }) }])} />}
          {section === "settings" && <Settings colors={colors} name={settingsName} phone={settingsPhone} address={settingsAddress} currency={settingsCurrency} width={settingsWidth} setName={setSettingsName} setPhone={setSettingsPhone} setAddress={setSettingsAddress} setCurrency={setSettingsCurrency} setWidth={setSettingsWidth} onSave={saveSettings} />}
          <View style={{ height: 95 }} />
        </ScrollView>
        <View style={[styles.tabBar, { backgroundColor: colors.surface, borderColor: colors.border }]}>
          <Tab icon="house.fill" label="الرئيسية" active={section === "home"} colors={colors} onPress={() => setSection("home")} />
          <Tab icon="doc.text.fill" label="الفواتير" active={section === "invoice"} colors={colors} onPress={() => setSection("invoice")} />
          <Tab icon="person.2.fill" label="الحسابات" active={section === "customers"} colors={colors} onPress={() => setSection("customers")} />
          <Tab icon="shippingbox.fill" label="المخزون" active={section === "stock"} colors={colors} onPress={() => setSection("stock")} />
          <Tab icon="clock.arrow.circlepath" label="التقارير" active={section === "reports"} colors={colors} onPress={() => setSection("reports")} />
        </View>
      </View>

      <KeyboardAvoidingView behavior={Platform.OS === "ios" ? "padding" : "height"} style={styles.keyboardLayer} pointerEvents="box-none">
        <Modal visible={showInvoice} animationType="slide" transparent onRequestClose={closeInvoice} statusBarTranslucent>
          <View style={styles.backdrop}><KeyboardAvoidingView behavior={Platform.OS === "ios" ? "padding" : "height"} style={styles.modalKeyboard}><View style={[styles.modal, { backgroundColor: colors.background }]}>
            <ModalHeader title={invoiceMode === "stock" ? "فاتورة من المخزن" : "فاتورة حرة"} colors={colors} close={closeInvoice} />
            <View style={styles.modeRow}><ModeButton active={invoiceMode === "stock"} label="فاتورة من المخزن" icon="shippingbox.fill" colors={colors} onPress={() => setInvoiceMode("stock")} /><ModeButton active={invoiceMode === "free"} label="فاتورة حرة" icon="doc.text.fill" colors={colors} onPress={() => setInvoiceMode("free")} /></View>
            {invoiceMode === "stock" ? <>
              <Text style={[styles.label, { color: colors.muted }]}>الحساب (اختياري)</Text>
              <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.pills}><Pill label="نقدي" active={customerId === null} colors={colors} onPress={() => setCustomerId(null)} />{customers.slice(0, 15).map((c: any) => <Pill key={c.id} label={c.name} active={customerId === c.id} colors={colors} onPress={() => setCustomerId(c.id)} />)}</ScrollView>
              <View style={[styles.searchBox, { backgroundColor: colors.surface, borderColor: colors.border }]}><IconSymbol name="magnifyingglass" size={18} color={colors.muted} /><TextInput value={search} onChangeText={setSearch} placeholder="ابحث عن صنف" placeholderTextColor={colors.muted} style={[styles.input, { color: colors.foreground }]} /></View>
              <FlatList data={products.slice(0, 25)} keyExtractor={(p: any) => String(p.id)} style={{ maxHeight: 220 }} keyboardShouldPersistTaps="handled" renderItem={({ item }) => <ProductRow p={item} colors={colors} onPress={() => addStockLine(item)} currency={settingsCurrency} />} />
              <Text style={[styles.sectionTitle, { color: colors.foreground }]}>الأصناف في الفاتورة</Text>
              {invoiceLines.map((x) => <View key={x.productId} style={[styles.lineRow, { borderBottomColor: colors.border }]}><View style={{ flex: 1 }}><Text style={[styles.rowTitle, { color: colors.foreground }]}>{x.name}</Text><Text style={[styles.rowSub, { color: colors.muted }]}>{x.quantity} × {money(x.price, settingsCurrency)}</Text></View><Pressable onPress={() => setInvoiceLines((old) => old.filter((y) => y.productId !== x.productId))}><IconSymbol name="trash" size={19} color={colors.danger} /></Pressable><Text style={[styles.price, { color: colors.primary }]}>{money(x.quantity * x.price, settingsCurrency)}</Text></View>)}
              <View style={styles.total}><Text style={[styles.totalLabel, { color: colors.muted }]}>الإجمالي</Text><Text style={[styles.totalValue, { color: colors.primary }]}>{money(draftTotal, settingsCurrency)}</Text></View>
              <Pressable disabled={createSale.isPending} onPress={saveStockInvoice} style={[styles.primaryButton, { backgroundColor: colors.primary }]}><Text style={styles.buttonText}>{createSale.isPending ? "جاري الحفظ..." : "حفظ الفاتورة"}</Text></Pressable>
            </> : <>
              <Field label="اسم الحساب / العميل" value={freeCustomer} onChangeText={setFreeCustomer} colors={colors} placeholder="اختياري" />
              <View style={[styles.formCard, { backgroundColor: colors.surface, borderColor: colors.border }]}><Text style={[styles.sectionTitle, { color: colors.foreground }]}>إضافة بند حر</Text><Field label="البيان" value={freeDescription} onChangeText={setFreeDescription} colors={colors} placeholder="مثال: خدمة أو صنف غير مسجل" /><View style={styles.two}><Field label="الكمية" value={freeQty} onChangeText={setFreeQty} colors={colors} placeholder="1" keyboardType="decimal-pad" /><Field label="سعر الوحدة" value={freePrice} onChangeText={setFreePrice} colors={colors} placeholder="0" keyboardType="decimal-pad" /></View><Pressable onPress={addFreeLine} style={[styles.primarySmall, { backgroundColor: colors.primary }]}><IconSymbol name="plus" size={18} color="#fff" /><Text style={styles.buttonText}>إضافة البند</Text></Pressable></View>
              {freeLines.map((x, i) => <View key={`${x.description}-${i}`} style={[styles.lineRow, { borderBottomColor: colors.border }]}><View style={{ flex: 1 }}><Text style={[styles.rowTitle, { color: colors.foreground }]}>{x.description}</Text><Text style={[styles.rowSub, { color: colors.muted }]}>{x.quantity} × {money(x.unitPrice, settingsCurrency)}</Text></View><Pressable onPress={() => setFreeLines((old) => old.filter((_, j) => j !== i))}><IconSymbol name="trash" size={19} color={colors.danger} /></Pressable><Text style={[styles.price, { color: colors.primary }]}>{money(x.quantity * x.unitPrice, settingsCurrency)}</Text></View>)}
              <View style={styles.total}><Text style={[styles.totalLabel, { color: colors.muted }]}>الإجمالي</Text><Text style={[styles.totalValue, { color: colors.primary }]}>{money(freeTotal, settingsCurrency)}</Text></View>
              <Pressable disabled={createFree.isPending} onPress={saveFreeInvoice} style={[styles.primaryButton, { backgroundColor: colors.primary }]}><Text style={styles.buttonText}>{createFree.isPending ? "جاري الحفظ..." : "حفظ الفاتورة الحرة"}</Text></Pressable>
            </>}
          </View></KeyboardAvoidingView></View>
        </Modal>

        <Modal visible={showCustomer} animationType="slide" transparent onRequestClose={closeCustomer} statusBarTranslucent><View style={styles.backdrop}><KeyboardAvoidingView behavior={Platform.OS === "ios" ? "padding" : "height"} style={styles.modalKeyboard}><View style={[styles.modal, { backgroundColor: colors.background }]}><ModalHeader title={customerId ? "تعديل الحساب" : "حساب جديد"} colors={colors} close={closeCustomer} /><ScrollView showsVerticalScrollIndicator={false}><Field label="اسم الحساب" value={customerName} onChangeText={setCustomerName} colors={colors} placeholder="اسم العميل" /><Field label="رقم الهاتف" value={customerPhone} onChangeText={setCustomerPhone} colors={colors} placeholder="رقم الجوال" keyboardType="phone-pad" /><Field label="العنوان" value={customerAddress} onChangeText={setCustomerAddress} colors={colors} placeholder="العنوان" /><Field label="ملاحظات" value={customerNotes} onChangeText={setCustomerNotes} colors={colors} placeholder="ملاحظات" /></ScrollView><Pressable onPress={saveCustomer} style={[styles.primaryButton, { backgroundColor: colors.primary }]}><Text style={styles.buttonText}>حفظ الحساب</Text></Pressable></View></KeyboardAvoidingView></View></Modal>

        <Modal visible={showProduct} animationType="slide" transparent onRequestClose={closeProduct} statusBarTranslucent><View style={styles.backdrop}><KeyboardAvoidingView behavior={Platform.OS === "ios" ? "padding" : "height"} style={styles.modalKeyboard}><View style={[styles.modal, { backgroundColor: colors.background }]}><ModalHeader title={productId ? "تعديل الصنف" : "إضافة صنف"} colors={colors} close={closeProduct} /><ScrollView showsVerticalScrollIndicator={false}><Field label="اسم الصنف" value={productName} onChangeText={setProductName} colors={colors} placeholder="اسم الصنف" /><View style={styles.two}><Field label="سعر الشراء" value={productPurchase} onChangeText={setProductPurchase} colors={colors} placeholder="0" keyboardType="decimal-pad" /><Field label="سعر البيع" value={productSale} onChangeText={setProductSale} colors={colors} placeholder="0" keyboardType="decimal-pad" /></View><View style={styles.two}><Field label="المخزون" value={productStock} onChangeText={setProductStock} colors={colors} placeholder="0" keyboardType="decimal-pad" /><Field label="الحد الأدنى" value={productMin} onChangeText={setProductMin} colors={colors} placeholder="0" keyboardType="decimal-pad" /></View></ScrollView><Pressable onPress={saveProduct} style={[styles.primaryButton, { backgroundColor: colors.primary }]}><Text style={styles.buttonText}>حفظ الصنف</Text></Pressable></View></KeyboardAvoidingView></View></Modal>

        <Modal visible={showAccount} animationType="slide" transparent onRequestClose={() => setShowAccount(false)} statusBarTranslucent><View style={styles.backdrop}><KeyboardAvoidingView behavior={Platform.OS === "ios" ? "padding" : "height"} style={styles.modalKeyboard}><View style={[styles.modal, { backgroundColor: colors.background }]}><ModalHeader title={accountQ.data?.customer?.name || "حساب العميل"} colors={colors} close={() => setShowAccount(false)} /><ScrollView showsVerticalScrollIndicator={false}>
          <View style={[styles.balanceHero, { backgroundColor: colors.primary }]}><Text style={styles.heroSmall}>الرصيد الحالي</Text><Text style={styles.heroValue}>{money(accountQ.data?.balance || 0, settingsCurrency)}</Text><Text style={styles.heroHint}>{accountQ.data?.customer?.phone || ""}</Text></View>
          <View style={styles.actionGrid}><Action icon="pencil" text="تعديل الحساب" onPress={() => { setShowAccount(false); editCustomer(accountQ.data?.customer); }} color={colors.primary} /><Action icon="square.and.arrow.up" text="مشاركة الحساب" onPress={accountShare} color="#2878C8" /><Action icon="printer.fill" text="طباعة الحساب" onPress={accountPrint} color="#8B5CF6" /></View>
          <View style={[styles.formCard, { backgroundColor: colors.surface, borderColor: colors.border }]}><Text style={[styles.sectionTitle, { color: colors.foreground }]}>إضافة دفعة</Text><View style={styles.two}><Field label="المبلغ" value={accountPaymentAmount} onChangeText={setAccountPaymentAmount} colors={colors} placeholder="0" keyboardType="decimal-pad" /><Field label="ملاحظة" value={accountPaymentNotes} onChangeText={setAccountPaymentNotes} colors={colors} placeholder="سداد" /></View><Pressable onPress={addPayment} style={[styles.primarySmall, { backgroundColor: colors.primary }]}><IconSymbol name="plus" size={18} color="#fff" /><Text style={styles.buttonText}>تسجيل الدفعة</Text></Pressable></View>
          <Text style={[styles.sectionTitle, { color: colors.foreground }]}>سجل الحساب</Text>
          {(accountQ.data?.invoices || []).map((x: any) => <OperationRow key={`i-${x.id}`} title={`فاتورة ${x.invoiceNo}`} subtitle={safeDate(x.createdAt)} amount={Number(x.total)} positive={false} colors={colors} onPress={() => { setShowAccount(false); showSaleDetail(x.id); }} />)}
          {(accountQ.data?.payments || []).map((x: any) => <OperationRow key={`p-${x.id}`} title="دفعة" subtitle={`${safeDate(x.createdAt)} · ${x.notes || ""}`} amount={Number(x.amount)} positive colors={colors} onEdit={() => { const amount = Number(x.amount); Alert.prompt?.("تعديل الدفعة", "المبلغ", (v) => updatePayment.mutate({ id: x.id, amount: Number(v) || amount, notes: x.notes || undefined }), "plain-text", String(amount)); }} onDelete={() => Alert.alert("حذف الدفعة", "هل تريد حذف العملية؟", [{ text: "إلغاء", style: "cancel" }, { text: "حذف", style: "destructive", onPress: () => deletePayment.mutate({ id: x.id }) }])} />)}
        </ScrollView></View></KeyboardAvoidingView></View></Modal>

        <Modal visible={showInvoiceDetail} animationType="slide" transparent onRequestClose={() => setShowInvoiceDetail(false)} statusBarTranslucent><View style={styles.backdrop}><KeyboardAvoidingView behavior={Platform.OS === "ios" ? "padding" : "height"} style={styles.modalKeyboard}><View style={[styles.modal, { backgroundColor: colors.background }]}><ModalHeader title={invoiceDetailQ.data?.invoice?.invoiceNo || freeDetailQ.data?.invoice?.invoiceNo || "تفاصيل العملية"} colors={colors} close={() => setShowInvoiceDetail(false)} /><ScrollView>
          {invoiceDetailQ.data && <InvoiceDetail data={invoiceDetailQ.data} colors={colors} currency={settingsCurrency} onShare={shareSaleDetail} onPrint={printSaleDetail} onDelete={() => deleteSaleConfirm(invoiceDetailQ.data!.invoice.id)} onEdit={() => Alert.alert("تعديل الفاتورة", "تم تجهيز التعديل على نفس شاشة الفاتورة؛ يمكنك إعادة فتحها من زر التعديل في الخطوة التالية.")} />}
          {freeDetailQ.data && <InvoiceDetail data={{ invoice: freeDetailQ.data.invoice, items: freeDetailQ.data.items.map((x: any) => ({ productName: x.description, quantity: x.quantity, unitPrice: x.unitPrice, total: x.total })) }} free colors={colors} currency={settingsCurrency} onShare={shareFreeDetail} onPrint={printFreeDetail} onDelete={() => deleteFreeConfirm(freeDetailQ.data!.invoice.id)} onEdit={() => Alert.alert("تعديل الفاتورة", "يمكن تعديل بنود الفاتورة الحرة من نفس البيانات عند فتحها مرة أخرى.")} />}
        </ScrollView></View></KeyboardAvoidingView></View></Modal>
      </KeyboardAvoidingView>
      {showMore && <Pressable onPress={() => setShowMore(false)} style={styles.moreOverlay}><View style={[styles.moreMenu, { backgroundColor: colors.surface, borderColor: colors.border }]}><Action icon="chart.bar.fill" text="التقارير والسجل" onPress={() => { setShowMore(false); setSection("reports"); }} color={colors.primary} /><Action icon="arrow.down.circle.fill" text="المصروفات" onPress={() => { setShowMore(false); setSection("expenses"); }} color={colors.warning} /><Action icon="gearshape.fill" text="الإعدادات" onPress={() => { setShowMore(false); setSection("settings"); loadSettings(); }} color="#2878C8" /></View></Pressable>}
    </ScreenContainer>
  );
}

function Home({ colors, report, lowStock, onStock, onFree, onCustomer, onProduct, onSection, activities, onActivity, currency }: any) { const r = report || {}; return <>
  <View style={[styles.hero, { backgroundColor: colors.primary }]}><View style={{ flex: 1 }}><Text style={styles.heroSmall}>إجمالي مبيعات اليوم</Text><Text style={styles.heroValue}>{money(r.totalSales || 0, currency)}</Text><Text style={styles.heroHint}>صافي الربح: {money(r.netProfit || 0, currency)}</Text></View><View style={styles.heroIcon}><IconSymbol name="chart.bar.fill" size={30} color="#D7F7E9" /></View></View>
  <View style={styles.grid}><Stat label="فواتير المخزن" value={String(r.invoices || 0)} icon="doc.text.fill" colors={colors} /><Stat label="الفواتير الحرة" value={String(r.freeInvoices || 0)} icon="doc.text.fill" colors={colors} /><Stat label="المصروفات" value={money(r.expenses || 0, currency)} icon="arrow.down.circle.fill" colors={colors} /></View>
  <View style={styles.invoiceChoice}><ModeButton active={false} label="فاتورة من المخزن" icon="shippingbox.fill" colors={colors} onPress={onStock} big /><ModeButton active={false} label="فاتورة حرة" icon="doc.text.fill" colors={colors} onPress={onFree} big /></View>
  <View style={styles.quickGrid}><Quick icon="person.badge.plus" text="حساب جديد" onPress={onCustomer} colors={colors} /><Quick icon="shippingbox.fill" text="إضافة صنف" onPress={onProduct} colors={colors} /><Quick icon="chart.bar.fill" text="التقارير" onPress={() => onSection("reports")} colors={colors} /><Quick icon="arrow.down.circle.fill" text="مصروف" onPress={() => onSection("expenses")} colors={colors} /></View>
  <View style={styles.sectionHead}><Text style={[styles.sectionTitle, { color: colors.foreground }]}>آخر العمليات</Text><Pressable onPress={() => onSection("reports")}><Text style={[styles.sectionAction, { color: colors.primary }]}>عرض السجل</Text></Pressable></View>
  {activities.map((x: any) => <ActivityRow key={x.id} x={x} colors={colors} currency={currency} onPress={() => onActivity(x)} />)}
  <View style={styles.sectionHead}><Text style={[styles.sectionTitle, { color: colors.foreground }]}>تنبيهات المخزون</Text><Text style={[styles.sectionAction, { color: colors.warning }]}>{lowStock.length} صنف منخفض</Text></View>
  {lowStock.slice(0, 4).map((p: any) => <View key={p.id} style={[styles.cardRow, { backgroundColor: colors.surface, borderColor: colors.border }]}><View style={[styles.dot, { backgroundColor: colors.warning }]}><IconSymbol name="exclamationmark.triangle.fill" size={15} color="#fff" /></View><View style={{ flex: 1 }}><Text style={[styles.rowTitle, { color: colors.foreground }]}>{p.name}</Text><Text style={[styles.rowSub, { color: colors.muted }]}>المتوفر {p.stock} · الحد الأدنى {p.minStock}</Text></View></View>)}
</>; }
function Invoices({ colors, invoices, freeInvoices, onNewStock, onNewFree, onOpen, onOpenFree, currency }: any) { return <><View style={styles.invoiceChoice}><ModeButton active={false} label="فاتورة من المخزن" icon="shippingbox.fill" colors={colors} onPress={onNewStock} big /><ModeButton active={false} label="فاتورة حرة" icon="doc.text.fill" colors={colors} onPress={onNewFree} big /></View><Text style={[styles.sectionTitle, { color: colors.foreground }]}>الفواتير المخزنية</Text>{invoices.map((x: any) => <Pressable key={x.id} onPress={() => onOpen(x.id)} style={[styles.cardRow, { backgroundColor: colors.surface, borderColor: colors.border }]}><View style={[styles.invoiceBadge, { backgroundColor: colors.primary + "18" }]}><IconSymbol name="doc.text.fill" size={17} color={colors.primary} /></View><View style={{ flex: 1 }}><Text style={[styles.rowTitle, { color: colors.foreground }]}>{x.invoiceNo}</Text><Text style={[styles.rowSub, { color: colors.muted }]}>{safeDate(x.createdAt)} · {x.paymentType === "cash" ? "نقدي" : "آجل"}</Text></View><Text style={[styles.price, { color: colors.primary }]}>{money(x.total, currency)}</Text></Pressable>)}<Text style={[styles.sectionTitle, { color: colors.foreground, marginTop: 12 }]}>الفواتير الحرة</Text>{freeInvoices.map((x: any) => <Pressable key={x.id} onPress={() => onOpenFree(x.id)} style={[styles.cardRow, { backgroundColor: colors.surface, borderColor: colors.border }]}><View style={[styles.invoiceBadge, { backgroundColor: "#2878C818" }]}><IconSymbol name="doc.text.fill" size={17} color="#2878C8" /></View><View style={{ flex: 1 }}><Text style={[styles.rowTitle, { color: colors.foreground }]}>{x.invoiceNo}</Text><Text style={[styles.rowSub, { color: colors.muted }]}>{safeDate(x.createdAt)} · {x.customerName || "بدون حساب"}</Text></View><Text style={[styles.price, { color: "#2878C8" }]}>{money(x.total, currency)}</Text></Pressable>)}</>; }
function Stock({ colors, products, lowStock, search, setSearch, onAdd, onEdit, currency }: any) { return <><View style={styles.actions}><Pressable onPress={onAdd} style={[styles.primarySmall, { backgroundColor: colors.primary }]}><IconSymbol name="plus" size={18} color="#fff" /><Text style={styles.buttonText}>إضافة صنف</Text></Pressable><Text style={[styles.counter, { color: colors.muted }]}>الأحدث تعديلًا أولًا · {products.length} صنف</Text></View><View style={[styles.searchBox, { backgroundColor: colors.surface, borderColor: colors.border }]}><IconSymbol name="magnifyingglass" size={18} color={colors.muted} /><TextInput value={search} onChangeText={setSearch} placeholder="بحث بالاسم أو الباركود" placeholderTextColor={colors.muted} style={[styles.input, { color: colors.foreground }]} /></View>{products.map((p: any) => <ProductRow key={p.id} p={p} colors={colors} onPress={() => onEdit(p)} currency={currency} />)}<Text style={[styles.rowSub, { color: colors.muted, marginTop: 4 }]}>الأصناف منخفضة المخزون: {lowStock.length}</Text></>; }
function Customers({ colors, customers, search, setSearch, onAdd, onEdit, onOpen, currency }: any) { return <><Pressable onPress={onAdd} style={[styles.primaryButton, { backgroundColor: colors.primary }]}><IconSymbol name="person.badge.plus" size={19} color="#fff" /><Text style={styles.buttonText}>حساب جديد</Text></Pressable><View style={[styles.searchBox, { backgroundColor: colors.surface, borderColor: colors.border }]}><IconSymbol name="magnifyingglass" size={18} color={colors.muted} /><TextInput value={search} onChangeText={setSearch} placeholder="ابحث عن الحساب" placeholderTextColor={colors.muted} style={[styles.input, { color: colors.foreground }]} /></View><Text style={[styles.rowSub, { color: colors.muted, marginBottom: 8 }]}>الأحدث تعديلًا أولًا</Text>{customers.map((c: any) => <Pressable key={c.id} onPress={() => onOpen(c)} style={[styles.cardRow, { backgroundColor: colors.surface, borderColor: colors.border }]}><View style={[styles.avatar, { backgroundColor: colors.primary + "18" }]}><Text style={[styles.avatarText, { color: colors.primary }]}>{c.name.slice(0, 1)}</Text></View><View style={{ flex: 1 }}><Text style={[styles.rowTitle, { color: colors.foreground }]}>{c.name}</Text><Text style={[styles.rowSub, { color: colors.muted }]}>{c.phone || "بدون هاتف"}</Text></View><View style={{ alignItems: "flex-end" }}><Text style={[styles.price, { color: Number(c.balance) > 0 ? colors.warning : colors.success }]}>{money(c.balance, currency)}</Text><View style={styles.inlineActions}><Pressable onPress={() => onEdit(c)}><IconSymbol name="pencil" size={18} color={colors.primary} /></Pressable></View></View></Pressable>)}</>; }
function Reports({ colors, report, activities, onOpenSale, onOpenFree, currency }: any) { const r = report || {}; return <><View style={[styles.reportHero, { backgroundColor: colors.surface, borderColor: colors.border }]}><Text style={[styles.reportCaption, { color: colors.muted }]}>ملخص التقارير</Text><Text style={[styles.reportMain, { color: colors.foreground }]}>{money(r.totalSales || 0, currency)}</Text><Text style={[styles.rowSub, { color: colors.muted }]}>مبيعات المخزن {money(r.sales || 0, currency)} · الحرة {money(r.freeSales || 0, currency)}</Text></View><View style={styles.grid}><Stat label="مجمل الربح" value={money(r.grossProfit || 0, currency)} icon="chart.bar.fill" colors={colors} /><Stat label="صافي الربح" value={money(r.netProfit || 0, currency)} icon="chart.bar.fill" colors={colors} /><Stat label="المشتريات" value={money(r.purchases || 0, currency)} icon="arrow.up.circle.fill" colors={colors} /></View><ReportRow label="تكلفة البضاعة المباعة" value={r.costOfGoods || 0} colors={colors} currency={currency} /><ReportRow label="المصروفات" value={r.expenses || 0} colors={colors} currency={currency} /><ReportRow label="الأصناف منخفضة" value={`${r.lowStock || 0} صنف`} colors={colors} raw /><Text style={[styles.sectionTitle, { color: colors.foreground, marginTop: 18 }]}>السجل الكامل للعمليات</Text>{activities.map((x: any) => <ActivityRow key={x.id} x={x} colors={colors} currency={currency} onPress={() => x.type === "sale" ? onOpenSale(x.referenceId) : x.type === "free" ? onOpenFree(x.referenceId) : undefined} />)}</>; }
function Expenses({ colors, expenses, category, amount, notes, setCategory, setAmount, setNotes, onSave, onEdit, onDelete }: any) { return <><View style={[styles.formCard, { backgroundColor: colors.surface, borderColor: colors.border }]}><Text style={[styles.sectionTitle, { color: colors.foreground }]}>{expenses.some((x: any) => x.id === undefined) ? "" : "إضافة / تعديل مصروف"}</Text><Field label="النوع" value={category} onChangeText={setCategory} colors={colors} placeholder="كهرباء، نقل، إيجار" /><Field label="المبلغ" value={amount} onChangeText={setAmount} colors={colors} placeholder="0" keyboardType="decimal-pad" /><Field label="ملاحظات" value={notes} onChangeText={setNotes} colors={colors} placeholder="اختياري" /><Pressable onPress={onSave} style={[styles.primaryButton, { backgroundColor: colors.primary }]}><Text style={styles.buttonText}>حفظ المصروف</Text></Pressable></View><Text style={[styles.sectionTitle, { color: colors.foreground }]}>آخر المصروفات</Text>{expenses.map((x: any) => <View key={x.id} style={[styles.cardRow, { backgroundColor: colors.surface, borderColor: colors.border }]}><View style={{ flex: 1 }}><Text style={[styles.rowTitle, { color: colors.foreground }]}>{x.category}</Text><Text style={[styles.rowSub, { color: colors.muted }]}>{safeDate(x.createdAt)} · {x.notes || ""}</Text></View><Text style={[styles.price, { color: colors.warning }]}>{Number(x.amount).toFixed(2)}</Text><Pressable onPress={() => onEdit(x)}><IconSymbol name="pencil" size={18} color={colors.primary} /></Pressable><Pressable onPress={() => onDelete(x.id)}><IconSymbol name="trash" size={18} color={colors.danger} /></Pressable></View>)}</>; }
function Settings({ colors, name, phone, address, currency, width, setName, setPhone, setAddress, setCurrency, setWidth, onSave }: any) { return <><View style={[styles.formCard, { backgroundColor: colors.surface, borderColor: colors.border }]}><Text style={[styles.sectionTitle, { color: colors.foreground }]}>إعدادات التطبيق والمتجر</Text><Field label="اسم المتجر" value={name} onChangeText={setName} colors={colors} placeholder="بقالة العزي للمواد الغذائية" /><Field label="الهاتف" value={phone} onChangeText={setPhone} colors={colors} placeholder="رقم الهاتف" keyboardType="phone-pad" /><Field label="العنوان" value={address} onChangeText={setAddress} colors={colors} placeholder="عنوان المتجر" /><Field label="العملة" value={currency} onChangeText={setCurrency} colors={colors} placeholder="ر.س" /><Text style={[styles.label, { color: colors.muted }]}>مقاس الإيصال</Text><View style={styles.pills}><Pill label="58mm" active={width === "58mm"} colors={colors} onPress={() => setWidth("58mm")} /><Pill label="80mm" active={width === "80mm"} colors={colors} onPress={() => setWidth("80mm")} /></View><Pressable onPress={onSave} style={[styles.primaryButton, { backgroundColor: colors.primary }]}><Text style={styles.buttonText}>حفظ الإعدادات</Text></Pressable></View><View style={[styles.formCard, { backgroundColor: colors.surface, borderColor: colors.border }]}><Text style={[styles.rowTitle, { color: colors.foreground }]}>الطباعة والمشاركة</Text><Text style={[styles.rowSub, { color: colors.muted }]}>يدعم التطبيق مشاركة PDF والطباعة بعرض 58mm أو 80mm، ويمكن إرسال الفاتورة من نافذة المشاركة إلى واتساب.</Text></View></>; }
function InvoiceDetail({ data, colors, currency, onShare, onPrint, onDelete, onEdit, free }: any) { return <><View style={[styles.reportHero, { backgroundColor: colors.surface, borderColor: colors.border }]}><Text style={[styles.reportCaption, { color: colors.muted }]}>{free ? "فاتورة حرة" : "فاتورة من المخزن"}</Text><Text style={[styles.reportMain, { color: colors.foreground }]}>{money(data.invoice.total, currency)}</Text><Text style={[styles.rowSub, { color: colors.muted }]}>{safeDate(data.invoice.createdAt)} · {data.invoice.customerName || data.customer?.name || "نقدي"}</Text></View>{data.items.map((x: any, i: number) => <View key={i} style={[styles.lineRow, { borderBottomColor: colors.border }]}><View style={{ flex: 1 }}><Text style={[styles.rowTitle, { color: colors.foreground }]}>{x.productName || x.description}</Text><Text style={[styles.rowSub, { color: colors.muted }]}>{Number(x.quantity)} × {money(x.unitPrice, currency)}</Text></View><Text style={[styles.price, { color: colors.primary }]}>{money(x.total, currency)}</Text></View>)}<View style={styles.actionGrid}><Action icon="pencil" text="تعديل" onPress={onEdit} color={colors.primary} /><Action icon="square.and.arrow.up" text="مشاركة PDF" onPress={onShare} color="#2878C8" /><Action icon="printer.fill" text="طباعة حرارية" onPress={onPrint} color="#8B5CF6" /><Action icon="trash" text="حذف" onPress={onDelete} color={colors.danger} /></View></>; }
function ActivityRow({ x, colors, currency, onPress }: any) { const color = x.type === "payment" ? colors.success : x.type === "expense" ? colors.warning : x.type === "free" ? "#2878C8" : colors.primary; return <Pressable onPress={onPress} style={[styles.activity, { backgroundColor: colors.surface, borderColor: colors.border }]}><View style={[styles.activityIcon, { backgroundColor: color + "18" }]}><IconSymbol name={x.type === "payment" ? "checkmark.circle.fill" : x.type === "expense" ? "arrow.down.circle.fill" : "doc.text.fill"} size={18} color={color} /></View><View style={{ flex: 1 }}><Text style={[styles.rowTitle, { color: colors.foreground }]}>{x.title}</Text><Text style={[styles.rowSub, { color: colors.muted }]}>{x.subtitle} · {safeDate(x.createdAt)}</Text></View><Text style={[styles.price, { color }]}>{money(x.amount, currency)}</Text></Pressable>; }
function ProductRow({ p, colors, onPress, currency }: any) { const low = Number(p.stock) <= Number(p.minStock); return <Pressable onPress={onPress} style={[styles.cardRow, { backgroundColor: colors.surface, borderColor: colors.border }]}><View style={[styles.dot, { backgroundColor: low ? colors.warning : colors.primary }]}><IconSymbol name="shippingbox.fill" size={15} color="#fff" /></View><View style={{ flex: 1 }}><Text style={[styles.rowTitle, { color: colors.foreground }]}>{p.name}</Text><Text style={[styles.rowSub, { color: colors.muted }]}>آخر تعديل · {safeDate(p.updatedAt)} · {p.unit} · مخزون {p.stock}</Text></View><View style={{ alignItems: "flex-end" }}><Text style={[styles.price, { color: colors.primary }]}>{money(p.salePrice, currency)}</Text><Text style={[styles.rowSub, { color: low ? colors.warning : colors.muted }]}>{low ? "منخفض" : "متوفر"}</Text></View></Pressable>; }
function OperationRow({ title, subtitle, amount, positive, colors, onPress, onEdit, onDelete }: any) { return <View style={[styles.cardRow, { backgroundColor: colors.surface, borderColor: colors.border }]}><Pressable onPress={onPress} style={{ flex: 1 }}><Text style={[styles.rowTitle, { color: colors.foreground }]}>{title}</Text><Text style={[styles.rowSub, { color: colors.muted }]}>{subtitle}</Text></Pressable><Text style={[styles.price, { color: positive ? colors.success : colors.warning }]}>{amount.toFixed(2)}</Text>{onEdit && <Pressable onPress={onEdit} style={styles.iconButton}><IconSymbol name="pencil" size={17} color={colors.primary} /></Pressable>}{onDelete && <Pressable onPress={onDelete} style={styles.iconButton}><IconSymbol name="trash" size={17} color={colors.danger} /></Pressable>}</View>; }
function ReportRow({ label, value, colors, currency, raw }: any) { return <View style={[styles.reportRow, { borderBottomColor: colors.border }]}><Text style={[styles.rowTitle, { color: colors.foreground }]}>{label}</Text><Text style={[styles.price, { color: colors.primary }]}>{raw ? value : money(value, currency)}</Text></View>; }
function Stat({ label, value, icon, colors }: any) { return <View style={[styles.stat, { backgroundColor: colors.surface, borderColor: colors.border }]}><IconSymbol name={icon} size={19} color={colors.primary} /><Text style={[styles.statLabel, { color: colors.muted }]}>{label}</Text><Text style={[styles.statValue, { color: colors.foreground }]}>{value}</Text></View>; }
function Quick({ icon, text, onPress, colors }: any) { return <Pressable onPress={onPress} style={[styles.quick, { backgroundColor: colors.surface, borderColor: colors.border }]}><View style={[styles.quickIcon, { backgroundColor: colors.primary + "18" }]}><IconSymbol name={icon} size={21} color={colors.primary} /></View><Text style={[styles.quickText, { color: colors.foreground }]}>{text}</Text></Pressable>; }
function Tab({ icon, label, active, colors, onPress }: any) { return <Pressable onPress={onPress} style={styles.tab}><IconSymbol name={icon} size={21} color={active ? colors.primary : colors.muted} /><Text style={[styles.tabText, { color: active ? colors.primary : colors.muted }]}>{label}</Text></Pressable>; }
function Pill({ label, active, colors, onPress }: any) { return <Pressable onPress={onPress} style={[styles.pill, { borderColor: active ? colors.primary : colors.border, backgroundColor: active ? colors.primary + "12" : colors.surface }]}><Text style={{ color: active ? colors.primary : colors.muted, fontWeight: "800" }}>{label}</Text></Pressable>; }
function ModeButton({ label, icon, active, colors, onPress, big }: any) { return <Pressable onPress={onPress} style={[styles.modeButton, { borderColor: active ? colors.primary : colors.border, backgroundColor: active ? colors.primary + "12" : colors.surface }, big && styles.modeBig]}><IconSymbol name={icon} size={big ? 25 : 18} color={active ? colors.primary : colors.muted} /><Text style={[styles.modeText, { color: active ? colors.primary : colors.foreground }]}>{label}</Text></Pressable>; }
function Action({ icon, text, onPress, color }: any) { return <Pressable onPress={onPress} style={styles.action}><View style={[styles.actionIcon, { backgroundColor: color + "18" }]}><IconSymbol name={icon} size={20} color={color} /></View><Text style={styles.actionText}>{text}</Text></Pressable>; }
function Field({ label, value, onChangeText, colors, placeholder, keyboardType }: any) { return <View style={{ flex: 1, marginBottom: 10 }}><Text style={[styles.label, { color: colors.muted }]}>{label}</Text><TextInput value={value} onChangeText={onChangeText} placeholder={placeholder} placeholderTextColor={colors.muted} keyboardType={keyboardType} style={[styles.formInput, { borderColor: colors.border, backgroundColor: colors.surface, color: colors.foreground }]} /></View>; }
function ModalHeader({ title, colors, close }: any) { return <View style={styles.modalHeader}><Text style={[styles.modalTitle, { color: colors.foreground }]}>{title}</Text><Pressable onPress={close} style={styles.close} hitSlop={8}><IconSymbol name="xmark" size={20} color={colors.muted} /></Pressable></View>; }

